css:
@page { size: A4; margin: 5mm; }
:root {
  --brand: #0f766e;
  --soft: #e7f4f2;
  --soft-2: #f3faf9;
  --ink: #12212b;
  --muted: #58707d;
  --line: #d5dde2;
  --card: #ffffff;
}
@font-face {
  font-family: 'CascadiaCode-Bold';
  src: url('/assets/tms/fonts/CascadiaCode-Bold.ttf') format('truetype');
  font-weight: 700;
  font-style: normal;
}
@font-face {
  font-family: 'Noto Naskh Arabic';
  src: url('/assets/tms/fonts/NotoNaskhArabic-VariableFont_wght.ttf') format('truetype');
  font-weight: 400 700;
  font-style: normal;
}
@font-face {
  font-family: 'SaudiRiyalSymbol';
  src: url('/assets/tms/fonts/saudiriyalsymbol.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
}
body {
  font-family: 'Ubuntu', 'Segoe UI', Arial, sans-serif;
  font-size: 8.2px;
  color: var(--ink);
}
.company-header-box {
  width: 100%;
  border-bottom: 1px solid var(--line);
  padding-bottom: 4px;
  margin-bottom: 4px;
}

.company-header-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.company-header-table td {
  vertical-align: top !important;
  border: 0 !important;
}

.company-info-en {
  width: 36%;
  text-align: left;
  direction: ltr;
  font-size: 9.6px;
  line-height: 1.32;
}

.company-info-ar {
  width: 36%;
  text-align: right;
  direction: rtl;
  font-family: 'Noto Naskh Arabic', serif;
  font-size: 9.7px;
  line-height: 1.32;
}

.company-logo-mid {
  width: 24%;
  text-align: center;
  vertical-align: middle !important;
}

.company-name-en {
  font-size: 12.2px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-name-ar {
  font-size: 12.8px;
  font-weight: 700;
  color: #000;
  margin-bottom: 4px;
}

.company-line {
  margin-bottom: 1.5px;
}

.company-label {
  font-weight: 600;
  color: var(--brand);
}

.invoice-title-center {
  text-align: center;
  font-size: 14px;
  font-weight: 700;
  margin-top: 4px;
  color: var(--brand);
}
.print-format {
  border-radius: 0 !important;
  padding: 2mm !important;
}
* { box-sizing: border-box; }
.invoice-shell { position: relative; }
.sheet {
  border: 0;
  border-radius: 0;
  padding: 0;
  background: #ffffff;
}
.hero {
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  padding: 0 0 10px;
  margin-bottom: 8px;
  background: #ffffff;
}
.hero-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.hero-grid td {
  vertical-align: middle !important;
}
.hero-title {
  font-size: 17px;
  font-weight: 600;
  line-height: 1.12;
  letter-spacing: 0;
  margin: 0;
  text-align: left;
}
.hero-subtitle {
  font-size: 16px;
  color: var(--ink);
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  margin: 9px 0 2px;
}
.badge {
  display: none;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--brand);
  color: white;
  font-size: 7.2px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.company-names {
  margin-top: 0;
}
.company-ar {
  font-family: 'Noto Naskh Arabic', serif !important;
  direction: rtl;
  text-align: right;
  font-size: 17px;
  font-weight: 600;
  color: #000;
  line-height: 1.12;
  unicode-bidi: plaintext;
  display: block;
  width: 100%;
  margin-top: 0;
}
.brand-logo-cell {
  width: 180px;
  text-align: center;
  padding: 0 14px !important;
}
.brand-logo-frame {
  display: inline-block;
  min-width: 156px;
  min-height: 82px;
  padding: 1px 3px;
  background: #fff;
  text-align: center;
  vertical-align: middle;
}
.brand-logo {
  display: block;
  max-width: 146px;
  max-height: 96px;
  width: auto;
  height: auto;
  margin: 0 auto;
  object-fit: contain;
  vertical-align: middle;
}

body .print-format .company-logo-mid img.brand-logo,
body .print-format .brand-logo-cell img.brand-logo{
  width: auto !important;
  max-width: 146px !important;
  max-height: 96px !important;
  height: auto !important;
}
.brand-logo-fallback {
  display: inline-block;
  margin-top: 18px;
  color: var(--brand);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.03em;
}
.hero-meta-wrap {
  margin-top: 3px;
}
.hero-meta {
  display: inline-block;
  min-width: 118px;
  margin: 0 8px 4px 0;
}
.hero-label {
  color: var(--muted);
  font-size: 7.2px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}
.hero-value {
  font-size: 8.8px;
  font-weight: 500;
  margin-top: 1px;
}
.qr-panel {
  width: 100%;
  margin: 0 auto;
  border: 0;
  border-radius: 0;
  background: white;
  padding: 0;
  text-align: center;
}
.qr-panel img {
  display: block;
  width: 86px;
  height: 86px;
  margin: 0 auto;
}
.qr-caption {
  margin-top: 3px;
  color: var(--muted);
  font-size: 6.8px;
  line-height: 1.1;
  text-align: center;
}
.summary-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
}
.summary-card {
  width: 49%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}
.summary-spacer {
  width: 2%;
}
.section-kicker {
  color: var(--brand);
  font-weight: 600;
  font-size: 7.4px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.mini-table {
  width: 100%;
  border-collapse: collapse;
}
.mini-table td {
  padding: 1.6px 0 !important;
  border-bottom: 1px dashed var(--line);
  vertical-align: top !important;
  line-height: 1.12;
}
.mini-table tr:last-child td {
  border-bottom: 0;
}
.mini-label {
  width: 33%;
  color: var(--muted);
  font-weight: 400;
}
.mini-value {
  width: 34%;
  font-weight: 500;
}
.mini-ar {
  font-family: 'Noto Naskh Arabic', serif;
  width: 33%;
  text-align: right;
  direction: rtl;
  color: var(--muted);
}
.party-grid {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin-top: 3px;
}
.party-grid > tbody > tr > td {
  border: 0 !important;
  padding: 0 !important;
  vertical-align: top !important;
}
.party-column {
  width: 49%;
}
.party-gap {
  width: 2%;
}
.party-card {
  width: 100%;
  min-height: 0;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
  page-break-inside: avoid;
}
.party-title {
  display: table;
  width: 100%;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 3px;
  
}
.party-title strong {
  display: table-cell;
  color: var(--brand);
  font-size: 9px;
  font-weight: 600;
}
.party-title span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  color: var(--brand);
  direction: rtl;
  text-align: right;
  font-size: 9px;
}
.party-name {
  display: none;
}
.party-name-ar {
  display: none;
}
.party-rows {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.party-rows td {
  padding: 1.4px 0 !important;
  border-bottom: 1px dashed var(--line) !important;
  vertical-align: top !important;
  line-height: 1.12;
}
.party-rows tr:last-child td {
  border-bottom: 0 !important;
}
.party-rows td:first-child {
  width: 28%;
  color: var(--muted);
  font-weight: 400;
}
.party-rows td:nth-child(2) {
  width: 46%;
  font-weight: 500;
  padding-right: 8px !important;
  overflow-wrap: anywhere;
  word-break: break-word;
}
.party-rows td:last-child {
  font-family: 'Noto Naskh Arabic', serif;
  width: 26%;
  direction: rtl;
  text-align: right;
  color: var(--muted);
}
.block {
  margin-top: 3px;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}
.block-head {
  display: table;
  width: 100%;
  margin-bottom: 3px;
}
.block-head strong {
  display: table-cell;
  color: var(--brand);
  font-size: 7.2px;
  font-weight: 600;
}
.block-head span {
  display: table-cell;
  font-family: 'Noto Naskh Arabic', serif;
  direction: rtl;
  text-align: right;
  color: var(--muted);
  font-size: 7.8px;
}
.items-table {
  width: 100%;
  border-collapse: collapse;
}
.items-table th,
.items-table td {
  border: 1px solid var(--line);
  padding: 2px 3px !important;
  vertical-align: top !important;
  line-height: 1.12;
}
.items-table thead th {
  background: var(--soft);
  color: var(--brand);
  font-size: 7.2px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}
.items-table .num {
  text-align: right;
  direction: ltr;
  white-space: nowrap;
}
.item-name {
  font-weight: 500;
}
.item-code {
  color: var(--muted);
  margin-top: 1px;
  font-size: 7.2px;
}
.totals-grid {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 3px;
}
.tax-card,
.totals-card {
  width: 49%;
  vertical-align: top;
  background: var(--card);
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  padding: 3px 0 0;
}
.totals-table,
.tax-table,
.bank-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}
.totals-table td,
.tax-table td,
.tax-table th,
.bank-table td {
  border: 1px solid var(--line);
  padding: 2px 3px !important;
  line-height: 1.12;
}
.totals-table td:first-child {
  color: var(--muted);
  font-weight: 400;
}
.totals-table td:last-child,
.tax-table td:last-child,
.tax-table td.num,
.bank-table td:last-child {
  text-align: right;
  direction: ltr;
}
.totals-table tr:last-child td {
  background: var(--brand);
  color: white;
  font-weight: 600;
}
.tax-table th {
  background: var(--soft-2);
  color: var(--brand);
  text-align: left;
  font-size: 7.2px;
  font-weight: 500;
}
.tax-table .num {
  text-align: right;
  direction: ltr;
}

.bank-table .bank-label {
  width: 18%;
  color: var(--muted);
  font-weight: 400;
}
.bank-table .bank-value {
  width: 42%;
  direction: ltr;
  text-align: left;
  font-weight: 500;
  word-break: break-word;
}
.bank-table .bank-label-ar {
  width: 22%;
  font-family: 'Noto Naskh Arabic', serif;
  color: var(--muted);
  text-align: right;
  direction: rtl;
  font-weight: 400;
}


.footnote {
  margin-top: 3px;
  border: 1px dashed var(--line);
  border-radius: 0;
  padding: 3px 0;
  color: var(--muted);
  line-height: 1.3;
}
.modern .hero {
  background: linear-gradient(135deg, var(--brand), #0b1720 68%);
  border-color: transparent;
  color: white;
}
.modern .hero-subtitle,
.modern .hero-label,
.modern .qr-caption,
.modern .company-ar {
  color: rgba(255,255,255,0.82);
}
.modern .badge {
  background: rgba(255,255,255,0.15);
  border: 1px solid rgba(255,255,255,0.16);
}
.modern .summary-card,
.modern .party-card,
.modern .tax-card,
.modern .totals-card,
.modern .block {
  background: #fbfdfe;
}
.minimal .sheet,
.minimal .hero,
.minimal .summary-card,
.minimal .party-card,
.minimal .tax-card,
.minimal .totals-card,
.minimal .block,
.minimal .footnote,
.minimal .qr-panel {
  border-radius: 0;
}
.minimal .badge,
.minimal .totals-table tr:last-child td {
  background: #161616;
}

.summary-grid, .party-grid, .totals-grid, .bank-table { page-break-inside: avoid; break-inside: avoid; }
.company-header-box, .summary-card, .party-card, .tax-card, .totals-card, .block { break-inside: avoid; page-break-inside: avoid; }
.items-table { page-break-inside: auto; break-inside: auto; }
.items-table tr { page-break-inside: avoid; break-inside: avoid; }

.currency-symbol {
  font-family: 'SaudiRiyalSymbol', 'Ubuntu', sans-serif;
  font-size: 1.05em;
  font-weight: normal;
  vertical-align: -0.02em;
}

.bank-table .bank-qr-cell {
  width: 20%;
  padding: 0 !important;
  text-align: center;
  vertical-align: middle !important;
  line-height: 0;
}
.bank-table .bank-qr-cell .qr-panel {
  width: 100%;
  max-width: 100%;
  aspect-ratio: 1 / 1;
  margin: 0;
  padding: 0;
  line-height: 0;
}
.bank-table .bank-qr-cell .qr-panel img {
  display: block;
  width: 100% !important;
  height: 100% !important;
  margin: 0;
  object-fit: contain;
}
.bank-table .bank-qr-cell .qr-caption {
  display: none;
}

[dir="rtl"], .mini-ar, .company-info-ar, .company-name-ar, .party-title span, .party-rows td:last-child, .block-head span, .bank-label-ar {
  font-family: 'Noto Naskh Arabic', serif !important;
}
